#!/usr/bin/env python3
"""regression-pytest.py — generate a pytest regression test from a regression artifact.

Usage:
    python3 regression-pytest.py <artifact-path> [--out tests/regression/]

Reads the regression artifact's frontmatter and body, emits a pytest test file
with a clear header, runnable structure, and assertions derived from the
Input and Expected output sections.

The generated test is INTENTIONALLY MINIMAL — it gives the team a working
skeleton, not a complete implementation. The team fills in the actual
function-under-test invocation in the marked section. This is by design:
auto-generating the call site would require knowing the team's import paths,
auth setup, fixtures, etc., which lives outside the artifact.

Logging: this script is invoked by /qa, which logs qa_tests_generated. The
script itself doesn't log.
"""

import argparse
import hashlib
import json
import re
import sys
from datetime import datetime, timezone
from pathlib import Path


def parse_frontmatter(text: str) -> tuple[dict, str]:
    """Return (frontmatter_dict, body_text). Empty dict if no frontmatter."""
    if not text.startswith("---\n"):
        return {}, text
    end = text.find("\n---\n", 4)
    if end < 0:
        return {}, text
    fm_text = text[4:end]
    body = text[end + 5:]
    fm = {}
    for line in fm_text.split("\n"):
        if ":" in line and not line.lstrip().startswith("#"):
            k, v = line.split(":", 1)
            fm[k.strip()] = v.strip()
    return fm, body


def extract_section(body: str, heading: str) -> str:
    """Extract the content of a markdown section by its H2 heading.

    Returns the content between '## <heading>' and the next '## ' or EOF.
    """
    pattern = re.compile(
        r"^##\s+" + re.escape(heading) + r"\s*\n(.*?)(?=^##\s|\Z)",
        re.MULTILINE | re.DOTALL,
    )
    m = pattern.search(body)
    return m.group(1).strip() if m else ""


def extract_code_block(section: str) -> tuple[str, str]:
    """Find the first fenced code block in a section. Returns (lang, content)."""
    m = re.search(r"```(\w*)\s*\n(.*?)```", section, re.DOTALL)
    if not m:
        return "", ""
    return m.group(1), m.group(2).rstrip()


def slugify(s: str) -> str:
    """Convert a string to a safe Python identifier fragment."""
    s = re.sub(r"[^a-zA-Z0-9]+", "_", s)
    s = re.sub(r"_+", "_", s).strip("_").lower()
    return s or "regression"


def content_hash(text: str) -> str:
    """Stable short hash of the artifact body. Used to detect hand edits."""
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def generate(artifact_path: Path, out_dir: Path) -> Path:
    """Read the artifact, generate a pytest test file, return the test file path."""
    text = artifact_path.read_text(encoding="utf-8")
    fm, body = parse_frontmatter(text)

    if fm.get("language") not in ("python", None, ""):
        raise SystemExit(
            f"regression-pytest.py only handles python artifacts; "
            f"this artifact's language is '{fm.get('language')}'"
        )

    why = extract_section(body, "Why this regression exists")
    input_section = extract_section(body, "Input")
    output_section = extract_section(body, "Expected output")
    verification = extract_section(body, "Verification command")

    if not input_section:
        raise SystemExit(f"Artifact {artifact_path} has no '## Input' section")
    if not output_section:
        raise SystemExit(f"Artifact {artifact_path} has no '## Expected output' section")

    input_lang, input_code = extract_code_block(input_section)
    output_lang, output_code = extract_code_block(output_section)

    # Try to parse input/output as JSON for clean fixture variables.
    # If not JSON, fall back to raw string fixtures.
    input_is_json = False
    output_is_json = False
    if input_lang in ("json", ""):
        try:
            json.loads(input_code)
            input_is_json = True
        except (json.JSONDecodeError, ValueError):
            pass
    if output_lang in ("json", ""):
        try:
            json.loads(output_code)
            output_is_json = True
        except (json.JSONDecodeError, ValueError):
            pass

    # Choose a test function name from the artifact filename
    stem = artifact_path.stem
    test_func_name = "test_regression_" + slugify(stem)

    # Compute the content hash for drift detection
    chash = content_hash(text)

    # Build the test file
    parts = []
    parts.append(f"""# AUTO-GENERATED by specship /qa. Do not edit by hand.
# §qa:{artifact_path.as_posix()}
# To change this test, edit the source artifact and re-run /qa.
# Content hash: {chash}
# Generated at: {datetime.now(timezone.utc).isoformat(timespec='seconds')}

\"\"\"Regression test for: {fm.get('regression_id', '<unknown>')}

Parent fix: {fm.get('parent_fix', '<unknown>')}
Authored by: {fm.get('authored_by', '<unknown>')}
Authored at: {fm.get('authored_at', '<unknown>')}

Why this regression exists:
{textwrap_indent(why or '(see source artifact)', '  ')}
\"\"\"

import json
import pytest
""")

    # Fixtures
    parts.append("\n# ---- Fixtures (extracted from the artifact's Input/Expected output) ----\n")
    if input_is_json:
        parts.append(f"REGRESSION_INPUT = json.loads(r'''{input_code}''')\n")
    else:
        parts.append(f"REGRESSION_INPUT = r'''{input_code}'''\n")

    if output_is_json:
        parts.append(f"EXPECTED_OUTPUT = json.loads(r'''{output_code}''')\n")
    else:
        parts.append(f"EXPECTED_OUTPUT = r'''{output_code}'''\n")

    # Test body
    parts.append(f"""

def {test_func_name}():
    \"\"\"Verify the regression fixed by {fm.get('parent_fix', '<unknown fix>')}.

    This test is auto-generated from a regression artifact. The CALL-SITE below
    is intentionally a placeholder — wire it up to the actual function or
    endpoint under test for your codebase.
    \"\"\"
    # =========================================================================
    # CALL SITE — replace this block with the actual invocation.
    # =========================================================================
    # Example for an HTTP API:
    #   from myapp.api import client
    #   response = client.post('/subscribe', json=REGRESSION_INPUT)
    #   actual = response.json()
    #
    # Example for a function:
    #   from myapp.module import the_function
    #   actual = the_function(REGRESSION_INPUT)
    #
    actual = None  # <-- REPLACE THIS
    pytest.skip(
        "Regression test stub — wire up the call site. "
        "Once wired, remove this skip() call."
    )
    # =========================================================================

    # ---- Assertions derived from the Expected output section ----
""")

    if output_is_json:
        parts.append("""    # The expected output was parsed as JSON. Asserts structural equality.
    # If the actual output is wrapped (e.g., {'data': ...}), unwrap first.
    assert actual == EXPECTED_OUTPUT, (
        f"Regression failed: actual={actual!r} expected={EXPECTED_OUTPUT!r}"
    )
""")
    else:
        parts.append("""    # The expected output is a raw string. Adapt the comparison to your
    # response type (str equality, .text match, .startswith, etc.).
    assert str(actual).strip() == EXPECTED_OUTPUT.strip(), (
        f"Regression failed: actual={actual!r} expected={EXPECTED_OUTPUT!r}"
    )
""")

    # If verification command is specified, include it as a docstring breadcrumb
    if verification:
        v_lang, v_cmd = extract_code_block(verification)
        if v_cmd:
            parts.append(f"\n\n# Verification command (from artifact):\n")
            for line in v_cmd.split("\n"):
                parts.append(f"#   {line}\n")

    content = "".join(parts)

    # Write the file
    out_dir.mkdir(parents=True, exist_ok=True)
    test_file = out_dir / f"test_{slugify(stem)}.py"
    test_file.write_text(content, encoding="utf-8")
    return test_file


def textwrap_indent(text: str, prefix: str) -> str:
    """Local helper to avoid importing textwrap for one function."""
    return "\n".join(prefix + line for line in text.split("\n"))


def main() -> int:
    p = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    p.add_argument("artifact", help="path to the regression artifact")
    p.add_argument("--out", default="tests/regression", help="output directory")
    args = p.parse_args()

    artifact_path = Path(args.artifact)
    if not artifact_path.is_file():
        print(f"artifact not found: {artifact_path}", file=sys.stderr)
        return 1

    try:
        test_file = generate(artifact_path, Path(args.out))
    except SystemExit as e:
        print(str(e), file=sys.stderr)
        return 1

    print(str(test_file))
    return 0


if __name__ == "__main__":
    sys.exit(main())
